    (v_chapter, 'mcq', 'scenario', 'bank', 5, 'A village near a volcano experiences poor air quality due to natural emissions. Which pollutant is likely released in large amounts?', '["Sulphur dioxide","Argon","Helium","Neon"]'::jsonb, 'A', 1, 'b6c8a1c3b91e', null),
